from __future__ import annotations

from string import Template

BASH_TMPL = Template(r"""
# =============================================================================
# zoxide bash integration (generated by `zoxide init bash`)

command -v zoxide >/dev/null 2>&1 || echo "zoxide: warning: 'zoxide' not found in PATH" >&2

__zoxide_hook() {
    zoxide add -- "$$(command pwd -L)"
}

if [[ "$$PROMPT_COMMAND" != *__zoxide_hook* ]]; then
    PROMPT_COMMAND="__zoxide_hook;$${PROMPT_COMMAND#;}"
fi

__zoxide_pwd() {
    command pwd -L
}

__zoxide_cd() {
    cd -- "$$@"
}

$cmd() {
    if [ "$$#" -eq 0 ]; then
        __zoxide_cd ~
    elif [ "$$#" -eq 1 ] && { [ "$$1" = "-" ] || [ "$$1" = "-." ]; }; then
        __zoxide_cd "$$1"
    elif [ "$$#" -eq 1 ] && [ -d "$$1" ]; then
        __zoxide_cd "$$1"
    elif [ "$$1" = "--" ]; then
        shift
        __zoxide_cd -- "$$@"
    else
        __zoxide_result="$$(zoxide query --exclude "$$(__zoxide_pwd)" -- "$$@")" && __zoxide_cd "$$__zoxide_result"
    fi
}

$zi_def

# =============================================================================
""")

BASH_ZI = Template(r"""
${cmd}i() {
    __zoxide_result="$$(zoxide query -i -- "$$@")" && __zoxide_cd "$$__zoxide_result"
}
""")

ZSH_TMPL = Template(r"""
# =============================================================================
# zoxide zsh integration (generated by `zoxide init zsh`)

command -v zoxide >/dev/null 2>&1 || echo "zoxide: warning: 'zoxide' not found in PATH" >&2

__zoxide_hook() {
    zoxide add -- "$${PWD:a}"
}

if [[ -z "$${precmd_functions[(r)__zoxide_hook]}" ]]; then
    precmd_functions+=(__zoxide_hook)
fi

__zoxide_cd() {
    builtin cd -- "$$@"
}

$cmd() {
    if [ "$$#" -eq 0 ]; then
        __zoxide_cd ~
    elif [ "$$#" -eq 1 ] && { [ "$$1" = "-" ] || [ "$$1" = "-." ]; }; then
        __zoxide_cd "$$1"
    elif [ "$$#" -eq 1 ] && [ -d "$$1" ]; then
        __zoxide_cd "$$1"
    elif [ "$$1" = "--" ]; then
        shift
        __zoxide_cd -- "$$@"
    else
        __zoxide_result="$$(zoxide query --exclude "$${PWD:a}" -- "$$@")" && __zoxide_cd "$$__zoxide_result"
    fi
}

$zi_def

# =============================================================================
""")

ZSH_ZI = Template(r"""
${cmd}i() {
    __zoxide_result="$$(zoxide query -i -- "$$@")" && __zoxide_cd "$$__zoxide_result"
}
""")

FISH_TMPL = Template(r"""
# =============================================================================
# zoxide fish integration (generated by `zoxide init fish`)

if not type -q zoxide
    echo "zoxide: warning: 'zoxide' not found in PATH" >&2
end

function __zoxide_hook --on-variable PWD
    zoxide add -- $$PWD
end

function __zoxide_cd
    cd $$argv
end

function $cmd
    if test (count $$argv) -eq 0
        __zoxide_cd $$HOME
    else if test "$$argv[1]" = "-"
        __zoxide_cd -
    else if test (count $$argv) -eq 1 -a -d "$$argv[1]"
        __zoxide_cd $$argv[1]
    else
        set -l result (zoxide query --exclude $$PWD -- $$argv)
        and __zoxide_cd $$result
    end
end

$zi_def

# =============================================================================
""")

FISH_ZI = Template(r"""
function ${cmd}i
    set -l result (zoxide query -i -- $$argv)
    and __zoxide_cd $$result
end
""")

POSIX_TMPL = Template(r"""
# =============================================================================
# zoxide POSIX-shell integration (generated by `zoxide init posix`)
# Note: automatic directory tracking requires a real prompt hook, which is
# shell-specific; only the "$cmd" jump function is provided here. Call
# `zoxide add -- "$$(pwd)"` manually (e.g. from .profile on login) if needed.

__zoxide_cd() {
    cd -- "$$@"
}

$cmd() {
    if [ "$$#" -eq 0 ]; then
        __zoxide_cd "$$HOME"
    elif [ "$$#" -eq 1 ] && [ "$$1" = "-" ]; then
        __zoxide_cd "$$1"
    elif [ "$$#" -eq 1 ] && [ -d "$$1" ]; then
        __zoxide_cd "$$1"
    else
        __zoxide_result=$$(zoxide query --exclude "$$(pwd)" -- "$$@") && __zoxide_cd "$$__zoxide_result"
    fi
}
# =============================================================================
""")


def render(shell: str, cmd: str = "z", hook: str = "pwd", no_cmd: bool = False, no_aliases: bool = False) -> str:
    if no_cmd:
        cmd = ""

    if shell == "bash":
        zi_def = "" if no_aliases else BASH_ZI.substitute(cmd=cmd or "z")
        return BASH_TMPL.substitute(cmd=cmd or "z", zi_def=zi_def).strip("\n") + "\n"
    if shell == "zsh":
        zi_def = "" if no_aliases else ZSH_ZI.substitute(cmd=cmd or "z")
        return ZSH_TMPL.substitute(cmd=cmd or "z", zi_def=zi_def).strip("\n") + "\n"
    if shell == "fish":
        zi_def = "" if no_aliases else FISH_ZI.substitute(cmd=cmd or "z")
        return FISH_TMPL.substitute(cmd=cmd or "z", zi_def=zi_def).strip("\n") + "\n"
    if shell == "posix":
        return POSIX_TMPL.substitute(cmd=cmd or "z").strip("\n") + "\n"

    raise ValueError(f"unsupported shell: {shell!r}")
